function tfd_language() {
	$lang = function_exists('pll_current_language') ? pll_current_language('slug') : apply_filters('wpml_current_language', null);
	return in_array($lang, array('vi','en','es'), true) ? $lang : 'vi';
}

function tfd_copy( $key ) {
	$catalogue = tfd_copy_catalogue();
	$values = $catalogue[$key] ?? array($key,$key,$key);
	$index = array('vi'=>0,'en'=>1,'es'=>2);
	$original = $values[0];
	$translated = function_exists('pll__') ? pll__($original) : apply_filters('wpml_translate_single_string',$original,'Trust Family Dental',$key);
	return $translated !== $original ? $translated : $values[$index[tfd_language()]];
}
